solve:{[tokens;codes]
   effective:();longs:();floats:();bools:();chars:();syms:();symIdx:();recast:0;i:0;
   while[i<count tokens;tok:tokens i;code:`$codes i;ok:0;attempts:enlist code;
     attempts,:?(`j`f`b`c`s) except enlist code;attempt:0;
     while[(attempt<count attempts)&not ok;ct:attempt . attempts;
       body:$[ct=`j;{(first . x) in "-";((count x)-1) . x} each (string til count tok);
         ct=`f;{"F"~type x} each (string til count tok);
         ct=`b;{"j"$lower x} each (string til count tok);ct=`c;{count x} each (string til count tok);ct=`s;1b];
       if[ct=`j;if[(all body)&((abs "J"$tok)<1000000000);effective,:enlist "j";longs,:enlist "J"$tok;ok:1]];
       if[ct=`f;if[(all body)&((abs "F"$tok)<1000000f);effective,:enlist "f";floats,:enlist 0.001*floor 0.5+1000f*("F"$tok);ok:1]];
       if[ct=`b;norm:"j"$lower tok;if[norm in "01tfalse";effective,:enlist "b";
         bools,:enlist 1*(norm in "1ttrue");ok:1]];
       if[ct=`c;if[(count tok)=1;effective,:enlist "c";chars,:enlist first tok;ok:1]];
       if[ct=`s;effective,:enlist "s";idx:$[tok in syms;syms?tok;syms,:enlist tok;count syms-1];
         symIdx,:enlist idx;ok:1];attempt+:1];
     if[code<>"j"$effective i;recast+:1];i+:1];
   `effective`longs`floats`bools`chars`syms`symIdx`recast`total!
     (effective;longs;floats;bools;chars;syms;symIdx;recast;
       0.001*floor 0.5+1000f*(sum longs)+sum floats+sum bools+sum chars+sum symIdx)}
