solve:{[tokens;codes]
  effective:();longs:();floats:();bools:();chars:();syms:();symidx:();recast:0;i:0;
  while[i<count tokens;tok:tokens i;attempted:0;done:0;
    order:$[codes[i]~"j";("f";"b";"c";"s");
      codes[i]~"f";("j";"b";"c";"s");
      codes[i]~"b";("j";"f";"c";"s");
      codes[i]~"c";("j";"f";"b";"s");("j";"f";"b";"c")];
    j:0;while[(j<count order)&not done;code:order j;attempted:1;valid:0;val:0f;
      if[code~"j";valid:(tok like "-?[0-9]+");
        if[valid;v:"J"$tok;valid:(abs v)<1000000000;val:v]];
      if[code~"f";valid:((tok like "-?[0-9]+")|(tok like "-?[0-9]+.[0-9]*")|(tok like "-?.[0-9]+"));
        if[valid;v:"F"$tok;valid:(abs v)<1000000f;val:0.001*floor 0.5+1000f*v]];
      if[code~"b";lc:lower tok;
        valid:((lc~"0")|(lc~"1")|(lc~"t")|(lc~"f")|(lc~"true")|(lc~"false"));
        if[valid;val:$[(lc~"1")|(lc~"t")|(lc~"true");1;0]]];
      if[code~"c";valid:(1=count tok);if[valid;val:"j"$first tok]];
      if[code~"s";valid:1;val:tok];
      if[valid;effective,:code;
        if[code~"j";longs,:val];
        if[code~"f";floats,:val];
        if[code~"b";bools,:val];
        if[code~"c";chars,:val];
        if[code~"s";
          ix:first where syms=string val;
          if[ix=count syms;syms,:enlist string val];symidx,:ix];
        if[not code~codes i;recast+:1];done:1];j+:1];
    if[not done;effective,:enlist "s";syms,:enlist string tok;symidx,:count syms-1;
      if[not "s"~codes i;recast+:1]];i+:1];
  `effective`longs`floats`bools`chars`syms`symIdx`recast`total!(
    string effective;longs;floats;bools;chars;syms;symidx;recast;
    0.001*floor 0.5+1000f*(sum longs)+sum floats+sum bools+sum chars+sum symidx)}
