solve:{[tokens;codes]
  j:"J"$;f:"F"$;b:{[x]
    x:lower x;$[x in ("1";"t";"true");1;0]};"S"$;
  names:`j`f`b`c`s;vals:(j;f;b;{first x};identity);
  effective:();longs:();floats:();bools:();chars:();syms:();symIdx:();recast:0;i:0;
  while[i<count tokens;
    t:tokens i;c:`$codes i;ok:0;j:0;
    while[(j<count names)&not ok;
      name:names j;
      if[name~c;ok:1];
      if[(name<>c)&ok not 1;
        ok:1;
        v:vals[j] t;
        if[name=`j;if[(v>=1000000000)|v<=-1000000000;ok:0]];
        if[name=`f;if[(v>=1000000f)|v<=-1000000f;ok:0]];
        if[name=`b;ok:1];
        if[name=`c;if[(count t)<>1;ok:0]]];
      j+:1];
    effective,:string names j;
    if[name=`j;longs,:v];
    if[name=`f;floats,:v];
    if[name=`b;bools,:v];
    if[name=`c;chars,:v];
    if[name=`s;
      if[not t in syms;syms,:enlist t];symIdx,:syms?t];
    if[not name~c;recast+:1];i+:1];
  `effective`longs`floats`bools`chars`syms`symIdx`recast`total!
    (effective;longs;floats;bools;chars;syms;symIdx;recast;
      0.001*floor 0.5+1000f*(sum longs)+sum floats+sum bools+sum chars+sum symIdx)}
