solve:{[tokens;codes]
   rnd:{[x;p] scale:10f xexp p;t:x*scale;low:floor t;low+:1*((t-low)>0.5)|(((t-low)=0.5)&(1=low mod 2));low%scale};
   effective:();longs:();floats:();bools:();chars:();syms:();symidx:();recast:0;i:0;
   while[i<count tokens;tok:tokens i;code:`$codes i;vals:();order:enlist code;
     if[not code~`j;order,:`j];if[not code~`f;order,:`f];
     if[not code~`b;order,:`b];if[not code~`c;order,:`c];if[not code~`s;order,:`s];
     j:0;while[j<count order;cur:order j;ok:0;val:0f;
       if[cur~`j;sign:1;body:tok;
         if[(first body)="-";sign:-1;body:1_body];
         if[(body~"" )|not all body in "0123456789";body:""];
         if[not body~"";v:"J"$body;
           if[abs v<1000000000;ok:1;val:sign*v]]];
       if[cur~`f;sign:1;body:tok;
         if[(first body)="-";sign:-1;body:1_body];
         if[(body~"" )|not all body in "0123456789.";body:""];
         if[not body~"";parts:"." vs body;
           if[(count parts)=1;v:"F"$first parts];
           if[(count parts)=2;v:("F"$first parts)+("F"$0.,"0",last parts)%10f xexp count last parts];
           if[abs v<1000000f;ok:1;val:rnd[sign*v;3]]];
       if[cur~`b;lo:lower tok;
         if[lo in ("0";"f";"false");ok:1;val:0f];
         if[lo in ("1";"t";"true");ok:1;val:1f]];
       if[cur~`c;if[(count tok)=1;ok:1;val:"J"$first tok]];
       if[cur~`s;ok:1;val:tok];
       if[ok;vals,:enlist (string cur;val);j:count order]];
     effective,:enlist first first vals;
     val:last first vals;
     if[first first vals~`j;longs,:enlist val];
     if[first first vals~`f;floats,:enlist val];
     if[first first vals~`b;bools,:enlist val];
     if[first first vals~`c;chars,:enlist val];
     if[first first vals~`s;
       idx:syms?val;$[idx<count syms;symidx,:enlist idx;syms,:enlist val;symidx,:enlist count syms-1]];
     if[not (first first vals)~code;recast+:1];i+:1];
   total:(sum longs)+(sum floats)+(sum bools)+(sum chars)+(sum symidx);
   `effective`longs`floats`bools`chars`syms`symIdx`recast`total!(effective;longs;floats;bools;chars;syms;symidx;recast;rnd[total;3])}
