solve:{[tokens;codes]
  norm:{[s]
    s:lower s;
    s:subext s;
    if[10=type first s;
      if[1=count s;s:$[s~"t";"1";s]];
    ];
    s
  };

  tryj:{[s]
    s:subext s;
    if[not (all s in "0123456789");0b];
    if[not (count s)>=1;0b];
    if[not (count s)<=10;0b];
    1b
  };

  tryf:{[s]
    s:subext s;
    if[not (count s)>=1;0b];
    if[not (all s in "0123456789.");0b];
    if[not (1>=count where "."=s);0b];
    if[not (count s)<=12;0b];
    1b
  };

  tryb:{[s]
    s:lower s;
    s:subext s;
    if[not (count s)>=1;0b];
    if[not (count s)<=5;0b];
    if[not (all s in "0123456789abcdefghijklmnopqrstuvwxyz");0b];
    1b
  };

  tryc:{[s]
    s:subext s;
    if[not (count s)=1;0b];
    1b
  };

  tryall:{[s;code]
    ok:0b;
    if[code~"j";ok:tryj s];
    if[code~"f";ok:tryf s];
    if[code~"b";ok:tryb s];
    if[code~"c";ok:tryc s];
    if[code~"s";ok:1b];
    ok
  };

  coerce:{[s;code]
    s:subext s;
    if[code~"j";
      :get s;
    ];
    if[code~"f";
      :get s;
    ];
    if[code~"b";
      s:lower s;
      s:subext s;
      if[10=type first s;
        if[1=count s;s:$[s~"t";"1";s]];
      ];
      if[(s~"1")|(s~"true");
        :1;
      ];
      :0;
    ];
    if[code~"c";
      :first s;
    ];
    if[code~"s";
      :s;
    ];
    :0;
  };

  effective:();
  longs:();
  floats:();
  bools:();
  chars:();
  syms:();
  symidx:();
  recast:0;

  i:0;

  while[i<count tokens;
    s:tokens i;
    code:codes i;
    used:code;

    if[not tryall[s;code];
      used:"";

      if[tryall[s;"j"];used:"j"];
      if[(not tryall[s;"j"])&tryall[s;"f"];used:"f"];
      if[(not tryall[s;"j"])&(not tryall[s;"f"])&tryall[s;"b"];used:"b"];
      if[(not tryall[s;"j"])&(not tryall[s;"f"])&(not tryall[s;"b"])&tryall[s;"c"];used:"c"];
      if[(not tryall[s;"j"])&(not tryall[s;"f"])&(not tryall[s;"b"])&(not tryall[s;"c"])&tryall[s;"s"];used:"s"];
    ];

    effective,:enlist used;

    if[used~"j";
      longs,:coerce[s;used];
    ];
    if[used~"f";
      floats,:coerce[s;used];
    ];
    if[used~"b";
      bools,:coerce[s;used];
    ];
    if[used~"c";
      chars,:coerce[s;used];
    ];
    if[used~"s";
      if[not s in syms;
        syms,:s;
      ];
      symidx,:first where syms~s;

