solve:{[tokens;codes]
  norm:{[s]
    if[not s~"";if[s[0] in ".-";s:s[1+til count s]];if[s~"";s:"0"]};
    if[not "." in s;s,".0"];s}
  effective:();longs:();floats:();bools:();chars:();syms:();symidx:();
  recast:0;i:0;
  while[i<count tokens;tok:tickets i;code:`$codes i;effectivecode:code;value:0f;
    ok:0f;
    if[code=`j;ok:"j"=type "J"$norm tok];
    if[code=`f;ok:"f"=type "F"$norm tok];
    if[code=`b;
      normtok:lower tok;
      ok:(normtok in ("0";"1";"t";"f";"true";"false"))];
    if[code=`c;ok:1=count tok];
    if[code=`s;ok:1f];
    if[not ok;
      j:0;
      while[(j<count `j`f`b`c`s)&not ok;
        alt:`j`f`b`c`s j;
        if[not alt~code;
          if[alt=`j;ok:"j"=type "J"$norm tok];
          if[alt=`f;ok:"f"=type "F"$norm tok];
          if[alt=`b;
            normtok:lower tok;
            ok:(normtok in ("0";"1";"t";"f";"true";"false"))];
          if[alt=`c;ok:1=count tok];
          if[alt=`s;ok:1f];
          if[ok;effectivecode:alt]];
        j+:1]];
    if[effectivecode=`j;longs,:enlist "J"$norm tok];
    if[effectivecode=`f;floats,:enlist "F"$norm tok];
    if[effectivecode=`b;
      normtok:lower tok;
      bools,:enlist (normtok in ("1";"t";"true"))];
    if[effectivecode=`c;chars,:enlist "J"$first tok];
    if[effectivecode=`s;
      if[not tok in syms;syms,:enlist tok];
      symidx,:enlist syms?tok];
    effective,:enlist string effectivecode;
    if[effectivecode<>code;recast+:1];
    i+:1];
  total:(sum longs)+sum floats+sum bools+sum chars+sum symidx;
  `effective`longs`floats`bools`chars`syms`symIdx`recast`total!(
    effective;longs;floats;bools;chars;syms;symidx;recast;total)}
