solve:{[tokens;codes]
  norm:{[s] lower s};
  longs:();floats:();bools:();chars:();syms:();symidx:();effective:();recast:0;total:0f;
  i:0;while[i<count tokens;t:tokens i;code:`$codes i;ok:0;
    if[not ok;if[(((count t)>=1)&((first t)<>"-"))|((first t)="-");
      if[(all (t&not "-"="") in "0123456789");
        v:"J"$t;if[(abs v)<1000000000;longs,:v;effective,:enlist "j";ok:1;total+:v]]]];
    if[not ok;
      v:"F"$t;if[(abs v)<1000000f;
        floats,:0.001*floor (v*1000f)+0.5f;effective,:enlist "f";ok:1;total+:last floats]];
    if[not ok;
      n:norm t;
      if[((n~"1")|(n~"t")|(n~"true"));bools,:1;effective,:enlist "b";ok:1;total+:1];
      if[not ok;if[((n~"0")|(n~"f")|(n~"false"));bools,:0;effective,:enlist "b";ok:1]]];
    if[not ok;if[(count t)=1;chars,:enlist .Q.A t;effective,:enlist "c";ok:1;total+:first chars]];
    if[not ok;effective,:enlist "s";idx:first where syms~enlist t;
      if[idx=count syms;syms,:enlist t;idx:count syms-1];symidx,:idx;total+:idx];
    if[not (`$effective i)~code;recast+:1];i+:1];
  `effective`longs`floats`bools`chars`syms`symIdx`recast`total!(string effective;longs;floats;bools;chars;syms;symidx;recast;0.001*floor (total*1000f)+0.5f)}
