solve:{[tokens;codes]
      rnd:{[x;p] scale:10f xexp p;t:x*scale;low:floor t;low+:1*((t-low)>0.5)|(((t-low)=0.5)&(1=low mod 2));low%scale};
      names:"j";names,"f";names,"b";names,"c";names,"s";
      effective:();longs:();floats:();bools:();chars:();syms:();symidx:();recast:0;
      i:0;while[i<count tokens;t:`$lower tokens i;code:`$codes i;names:names except code;
        ok:0;j:0;while[(j<count names)&not ok;nc:names j;
          ok:((nc~`s)|(nc~`c)&(1=count tokens i))|
            ((nc~`b)&((t~`0)|(t~`1)|(t~`t)|(t~`f)|(t~`true)|(t~`false)))|
            ((nc~`j)&((first tokens i)~"-")|(first tokens i) in "0123456789")|
            ((nc~`f)&((first tokens i)~"-")|(first tokens i) in ".0123456789");
          if[ok;effective,:nc;
            if[nc~`j;longs,:raze "J"$tokens i];
            if[nc~`f;floats,:raze rnd["F"$tokens i;3]];
            if[nc~`b;bools,:1*(t~`1)|(t~`t)|(t~`true)];
            if[nc~`c;chars,:raze "J"$first tokens i];
            if[nc~`s;if[not t in syms;syms,:t];symidx,:syms?t]];
          j+:1];i+:1];
      effective:raze effective;
      if[recast>0;recast:count where (`$effective)<>(`$codes)];
      `effective`longs`floats`bools`chars`syms`symIdx`recast`total!(
        effective;longs;floats;bools;chars;syms;symidx;recast;
        rnd[sum longs+floats+bools+chars+symidx;3])}
